// TR069 IP - Normalized & Multi-vendor
let result = '';

if (args[1] && "value" in args[1]) {
    result = args[1].value[0];
}

// 1. Try ConnectionRequestURL first (most accurate for TR-069 communication)
if (!result || result === '' || result === '0.0.0.0') {
    let crUrl = declare("InternetGatewayDevice.ManagementServer.ConnectionRequestURL", {value: 1});
    if (crUrl && crUrl.value && crUrl.value[0]) {
        let m = String(crUrl.value[0]).match(/https?:\/\/([^:/]+)/);
        if (m && m[1] && m[1] !== '0.0.0.0') {
            result = m[1];
        }
    }
}

// 2. Fallback to WAN IP connections if needed
if (!result || result === '' || result === '0.0.0.0') {
    let keys = [
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.1.WANIPConnection.1.ExternalIPAddress',
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.1.WANIPConnection.2.ExternalIPAddress',
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.2.WANIPConnection.1.ExternalIPAddress',
        'Device.IP.Interface.1.IPv4Address.1.IPAddress'
    ];
    for (let key of keys) {
        let d = declare(key, {value: 1});
        if (d && d.value && d.value[0] && d.value[0] !== '0.0.0.0') {
            result = d.value[0];
            break;
        }
    }
}

return {writable: false, value: [result || '', "xsd:string"]};

// VirtualParameter: pppoeMac (Multi-vendor TR-098 & TR-181)
let result = "";

function isValidMac(s) {
  if (!s || typeof s !== 'string') return false;
  s = s.trim();
  if (s === '00:00:00:00:00:00' || s === 'ff:ff:ff:ff:ff:ff' || s === '00-00-00-00-00-00') return false;
  return /^([0-9A-Fa-f]{2}[:-]){5}([0-9A-Fa-f]{2})$/.test(s);
}

// 1. WANPPPConnection MACs across all WANDevices and WANConnectionDevices
let w1 = declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.MACAddress", {value: Date.now()});
for (let p of w1) {
  if (p.value && isValidMac(p.value[0])) {
    result = p.value[0];
    break;
  }
}

// 2. WANIPConnection MACs
if (!result) {
  let w2 = declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANIPConnection.*.MACAddress", {value: Date.now()});
  for (let p of w2) {
    if (p.value && isValidMac(p.value[0])) {
      result = p.value[0];
      break;
    }
  }
}

// 3. F477V2 EPON specific Serial/MAC
if (!result) {
  let w3 = declare("InternetGatewayDevice.DeviceInfo.X_CU_SerialNumber", {value: Date.now()});
  if (w3.size && isValidMac(w3.value[0])) {
    result = w3.value[0];
  }
}

// 4. DeviceInfo MACAddress
if (!result) {
  let w4 = declare("InternetGatewayDevice.DeviceInfo.MACAddress", {value: Date.now()});
  if (w4.size && isValidMac(w4.value[0])) {
    result = w4.value[0];
  }
}

// 5. LANDevice LANHostConfigManagement MAC
if (!result) {
  let w5 = declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.MACAddress", {value: Date.now()});
  if (w5.size && isValidMac(w5.value[0])) {
    result = w5.value[0];
  }
}

// 6. WLAN BSSID fallback
if (!result) {
  let w6 = declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.BSSID", {value: Date.now()});
  if (w6.size && isValidMac(w6.value[0])) {
    result = w6.value[0];
  }
}

// 7. TR-181 standard Ethernet Interface MAC
if (!result) {
  let w7 = declare("Device.Ethernet.Interface.*.MACAddress", {value: Date.now()});
  for (let p of w7) {
    if (p.value && isValidMac(p.value[0])) {
      result = p.value[0];
      break;
    }
  }
}

return {writable: false, value: [result, "xsd:string"]};

// RXPower
let m = "N/A";
let db = "";
let zte = declare("InternetGatewayDevice.WANDevice.*.X_ZTE-COM_WANPONInterfaceConfig.RXPower", {value: Date.now()});
let huawei = declare("InternetGatewayDevice.WANDevice.*.X_GponInterafceConfig.RXPower", {value: Date.now()});
let fiberhome = declare("InternetGatewayDevice.WANDevice.*.X_FH_GponInterfaceConfig.RXPower", {value: Date.now()});
let ztecmcc = declare("InternetGatewayDevice.WANDevice.*.X_CMCC_EponInterfaceConfig.RXPower" , {value: Date.now()});
let ztecmcg = declare("InternetGatewayDevice.WANDevice.*.X_CMCC_GponInterfaceConfig.RXPower" , {value: Date.now()});
let gm220se = declare("InternetGatewayDevice.WANDevice.*.X_CT-COM_EponInterfaceConfig.RXPower" , {value: Date.now()});
let gm220sg = declare("InternetGatewayDevice.WANDevice.*.X_CT-COM_GponInterfaceConfig.RXPower" , {value: Date.now()});
let f477v2 = declare("InternetGatewayDevice.WANDevice.*.X_CU_WANEPONInterfaceConfig.OpticalTransceiver.RXPower"	, {value: Date.now()});
let nokia = declare("InternetGatewayDevice.X_ALU_OntOpticalParam.RXPower" , {value: Date.now()});

if (zte.size) {
   let zteval = zte.value[0]
   if (zteval < 0) {
      m = zteval;

    }
    else if (zteval > 0) {
      db = 30 + (Math.log10((zteval * (Math.pow(10,-7))))*10);
	  m = Math.ceil(db * 100) / 100;
    }
}
else if (ztecmcc.size) {
   let zteval = ztecmcc.value[0]
   if (zteval < 0) {
      m = zteval;

    }
    else if (zteval > 0) {
      db = 30 + (Math.log10((zteval * (Math.pow(10,-7))))*10);
	  m = Math.ceil(db * 100) / 100;
    }
}
else if (ztecmcg.size) {
   let zteval = ztecmcg.value[0]
   if (zteval < 0) {
      m = zteval;

    }
    else if (zteval > 0) {
      db = 30 + (Math.log10((zteval * (Math.pow(10,-7))))*10);
	  m = Math.ceil(db * 100) / 100;
    }
}
else if (gm220se.size) {
   let zteval = gm220se.value[0]
   if (zteval < 0) {
      m = zteval;

    }
    else if (zteval > 0) {
      db = 30 + (Math.log10((zteval * (Math.pow(10,-7))))*10);
	  m = Math.ceil(db * 100) / 100;
    }
}
else if (gm220sg.size) {
   let zteval = gm220sg.value[0]
   if (zteval < 0) {
      m = zteval;

    }
    else if (zteval > 0) {
      db = 30 + (Math.log10((zteval * (Math.pow(10,-7))))*10);
	  m = Math.ceil(db * 100) / 100;
    }
}
else if (f477v2.size) {
   let zteval = f477v2.value[0]
   if (zteval < 0) {
      m = zteval;

    }
    else if (zteval > 0) {
      db = 30 + (Math.log10((zteval * (Math.pow(10,-7))))*10);
	  m = Math.ceil(db * 100) / 100;
    }
}
else if (huawei.size) {
  for (let p of huawei) {
    if (p.value[0]) {
      m = p.value[0];
      break;
    }
  }
}
else if (fiberhome.size) {
  for (let p of fiberhome) {
    if (p.value[0]) {
      m = p.value[0];
      break;
    }
  }
}
else if (nokia.size) {
  for (let p of nokia) {
    if (p.value[0]) {
      m = p.value[0];
      break;
    }
  }
}
return {writable: false, value: [m, "xsd:string"]};

// Total active all ssid (Multi-Vendor TR-098 & TR-181)
let active = 0;
let isNumber = (val) => typeof val === 'number' && isFinite(val) && val >= 0;

// 1. Standard TR-098: Check TotalAssociations across WLAN 1..8
for (let i = 1; i <= 8; i++) {
  let ta = declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration." + i + ".TotalAssociations", {value: Date.now()});
  if (ta && ta.size && isNumber(ta.value[0])) {
    active += ta.value[0];
  }
}

// 2. Vendor Fallback: WLAN_AssociatedDeviceNumberOfEntries (FiberHome HG6243C / others)
if (active === 0) {
  for (let i = 1; i <= 8; i++) {
    let ne = declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration." + i + ".WLAN_AssociatedDeviceNumberOfEntries", {value: Date.now()});
    if (ne && ne.size && isNumber(ne.value[0])) {
      active += ne.value[0];
    }
  }
}

// 3. Fallback: Count AssociatedDevice entries directly
if (active === 0) {
  let assoc = declare("InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.AssociatedDevice.*.AssociatedDeviceMACAddress", {value: Date.now()});
  if (assoc && assoc.size) {
    active = assoc.size;
  }
}

// 4. TR-181 Standard Fallback
if (active === 0) {
  let tr181 = declare("Device.WiFi.AccessPoint.*.AssociatedDevice.*.MACAddress", {value: Date.now()});
  if (tr181 && tr181.size) {
    active = tr181.size;
  }
}

return {writable: false, value: [active, "xsd:int"]};

// serial number
let serialNumber = "";
let sn = "";
let hexPart = "";

// Hex To Text
let hexToText = (hex) => {
  let text = "";
  for (let i = 0; i < hex.length; i += 2) {
    let hexCode = hex.substr(i, 2);
    let charCode = parseInt(hexCode, 16);
    text += String.fromCharCode(charCode);
  }
  return text;
};
// Check Hex Or String
let isHexadecimal = (str) => {
  return /^[0-9A-Fa-f]+$/.test(str);
};
let ponmode = "";
let pon = declare("VirtualParameters.getponmode", {value: Date.now()});
  if (pon.size) {
    ponmode = pon.value[0];
  }
if (args[1].value) {
  serialNumber = args[1].value[0];
  if (!isHexadecimal(serialNumber)) {
    sn = serialNumber;
  } else if (serialNumber.includes("40ee15")) {
    sn = serialNumber;
  } else if (ponmode.includes("EPON")) {
    sn = serialNumber;
  } else {
    hexPart = serialNumber.substr(0, 8);
    let textPart = hexToText(hexPart);
    sn = textPart + serialNumber.substr(8);
  }
  declare("DeviceID.SerialNumber", null, {value: serialNumber});
}
else {
  let snvalue = declare("DeviceID.SerialNumber", {value: Date.now()});
  serialNumber = snvalue.value[0];
  if (!isHexadecimal(serialNumber)) {
    sn = serialNumber;
  } else if (serialNumber.includes("40ee15")) {
    sn = serialNumber;
  } else if (ponmode.includes("EPON")) {
    sn = serialNumber;
  } else {
    hexPart = serialNumber.substr(0, 8);
    let textPart = hexToText(hexPart);
    sn = textPart + serialNumber.substr(8);
  }
}

return {writable: false, value: sn};

// Device Uptime
let totalSecs = "";
const brand = declare('DeviceID.Manufacturer', {value: 1}).value[0];

if (args[1].value) {
  totalSecs = args[1].value[0];
  if (brand !== 'MikroTik') {
    declare("InternetGatewayDevice.DeviceInfo.UpTime", null, {value: totalSecs});
  } else {
    declare("Device.DeviceInfo.UpTime", null, {value: totalSecs});
  }
}
else {
  if (brand !== 'MikroTik') {
    totalSecs = declare("InternetGatewayDevice.DeviceInfo.UpTime", {value: Date.now()}).value[0];
  } else {
    totalSecs = declare("Device.DeviceInfo.UpTime", {value: Date.now()}).value[0];
  }
}
let days = Math.floor(totalSecs / 86400);
let rem  = totalSecs % 86400;
let hrs  = Math.floor(rem / 3600);
if (hrs < 10) {
	hrs = "0" + hrs;
}

rem  = rem % 3600;
let mins = Math.floor(rem / 60);
if (mins < 10) {
	mins = "0" + mins;
}
let secs = rem % 60;
if (secs < 10) {
	secs = "0" + secs;
}

let up = days + "d " + hrs + ":" + mins + ":" + secs;

return {writable: false, value: up};

// Mendapatkan informasi PON
let pon = "";
if (args[1].value) {
  pon = args[1].value[0];
  declare("InternetGatewayDevice.DeviceInfo.X_HW_UpPortMode", {value: Date.now()});

}
else {

  let v1 = declare("InternetGatewayDevice.WANDevice.*.WANCommonInterfaceConfig.WANAccessType", {value: Date.now()});

  if (v1.size) {
    pon = v1.value[0];
  }
}

pon = pon.toUpperCase();

const brand = declare('DeviceID.Manufacturer', {value: Date.now(86400000)}).value[0];
if (brand === 'RAISECOM' || brand === 'Raisecom' ) {
  pon = "GPON";
} else if (pon.includes("EPON")) {
  pon = "EPON";
} else if (pon.includes("GPON")) {
  pon = "GPON";
} else if (pon.includes("PON")) {
  pon = "GPON";
} else {
  pon = "Ethernet";
}


return {writable: false, value: [pon, "xsd:string"]};

// uptime
let totalSecs = "";
if (args[1].value) {
  totalSecs = args[1].value[0];
  declare("InternetGatewayDevice.WANDevice.1.WANConnectionDevice.*.WANPPPConnection.*.Uptime", null, {value: totalSecs});
  declare("InternetGatewayDevice.DeviceInfo.UpTime", null, {value: totalSecs});

}
else {
  let v1 = declare("InternetGatewayDevice.WANDevice.1.WANConnectionDevice.*.WANPPPConnection.*.Uptime", {value: Date.now()});
  let v2 = declare("InternetGatewayDevice.DeviceInfo.UpTime", {value: Date.now()});
//  totalSecs = v1.value[0];
  if (v1.size) {
    totalSecs = v1.value[0];
  }
}
let days = Math.floor(totalSecs / 86400);
let rem  = totalSecs % 86400;
let hrs  = Math.floor(rem / 3600);
if (hrs < 10) {
	hrs = "0" + hrs;
}

rem  = rem % 3600;
let mins = Math.floor(rem / 60);
if (mins < 10) {
	mins = "0" + mins;
}
let secs = rem % 60;
if (secs < 10) {
	secs = "0" + secs;
}

let up = days + "d " + hrs + ":" + mins + ":" + secs;

return {writable: false, value: up};

// Parameter pengukuran Temperatur pada perangkat berbeda (Multi-vendor Normalized)
let m = "N/A";

const tempPaths = [
  "InternetGatewayDevice.WANDevice.1.X_CU_WANEPONInterfaceConfig.OpticalTransceiver.Temperature",
  "InternetGatewayDevice.WANDevice.1.X_CU_WANGPONInterfaceConfig.OpticalTransceiver.Temperature",
  "InternetGatewayDevice.WANDevice.1.X_CMCC_EponInterfaceConfig.TransceiverTemperature",
  "InternetGatewayDevice.WANDevice.1.X_CMCC_GponInterfaceConfig.TransceiverTemperature",
  "InternetGatewayDevice.WANDevice.1.X_CT-COM_GponInterfaceConfig.TransceiverTemperature",
  "InternetGatewayDevice.WANDevice.1.X_CT-COM_EponInterfaceConfig.TransceiverTemperature",
  "InternetGatewayDevice.WANDevice.1.X_ZTE-COM_WANPONInterfaceConfig.TransceiverTemperature",
  "InternetGatewayDevice.WANDevice.1.X_GponInterafceConfig.TransceiverTemperature",
  "InternetGatewayDevice.WANDevice.1.X_FH_GponInterfaceConfig.TransceiverTemperature",
  "InternetGatewayDevice.DeviceInfo.Temperature"
];

for (let p of tempPaths) {
  let d = declare(p, {value: Date.now()});
  if (d.size && d.value && d.value[0] !== undefined) {
    let raw = Number(d.value[0]);
    if (isNaN(raw) || raw <= 15) continue;

    // Standard DDM 1/256 degree Celsius scaling (e.g. 10141 -> ~40C, 12035 -> 47C)
    if (raw >= 150) {
      let deg = Math.round(raw / 256);
      if (deg >= 20 && deg <= 100) {
        m = String(deg);
        break;
      }
    } else if (raw >= 20 && raw <= 100) {
      m = String(Math.round(raw));
      break;
    }
  }
}

return {writable: false, value: [m, "xsd:string"]};

// pppoeIP New
let result = '';

if ("value" in args[1]) {
    result = args[1].value[0];
}

if (result === '') {
    let keys = [
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.1.WANPPPConnection.1.ExternalIPAddress',
        'InternetGatewayDevice.WANDevice.*.WANConnectionDevice.1.WANPPPConnection.2.ExternalIPAddress',
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.2.WANPPPConnection.1.ExternalIPAddress',
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.2.WANPPPConnection.2.ExternalIPAddress',
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.3.WANPPPConnection.1.ExternalIPAddress',
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.4.WANPPPConnection.1.ExternalIPAddress',
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.5.WANPPPConnection.1.ExternalIPAddress',
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.5.WANPPPConnection.1.ExternalIPAddress',
        'InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.ExternalIPAddress',
        'Device.IP.Interface.1.IPv4Address.1.IPAddress'
    ];

    result = getParameterValue(keys);
}

log("pppoeIP: " + result);
return {writable: false, value: [result, "xsd:string"]};

function getParameterValue(keys) {
    for (let key of keys) {
        if (key.includes('WANPPPConnection.1.ExternalIPAddress')) {
            let connectionTypeKey = key.replace('ExternalIPAddress', 'ConnectionType');
            let connectionType = declare(connectionTypeKey, {value: Date.now()});
            if (connectionType.size && connectionType.value[0] === 'bridge') {
                continue;
            }
        }

        let d = declare(key, {path: Date.now() - (120 * 1000), value: Date.now()});

        for (let item of d) {
            if (item.value && item.value[0] && item.value[0] !== '0.0.0.0') {
                return item.value[0];
            }
        }
    }

    return '';
}

// VirtualParameter: pppoeMac (Multi-vendor TR-098 & TR-181)
let result = "";

function isValidMac(s) {
  if (!s || typeof s !== 'string') return false;
  s = s.trim();
  if (s === '00:00:00:00:00:00' || s === 'ff:ff:ff:ff:ff:ff' || s === '00-00-00-00-00-00') return false;
  return /^([0-9A-Fa-f]{2}[:-]){5}([0-9A-Fa-f]{2})$/.test(s);
}

// 1. WANPPPConnection MACs across all WANDevices and WANConnectionDevices
let w1 = declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.MACAddress", {value: Date.now()});
for (let p of w1) {
  if (p.value && isValidMac(p.value[0])) {
    result = p.value[0];
    break;
  }
}

// 2. WANIPConnection MACs
if (!result) {
  let w2 = declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANIPConnection.*.MACAddress", {value: Date.now()});
  for (let p of w2) {
    if (p.value && isValidMac(p.value[0])) {
      result = p.value[0];
      break;
    }
  }
}

// 3. F477V2 EPON specific Serial/MAC
if (!result) {
  let w3 = declare("InternetGatewayDevice.DeviceInfo.X_CU_SerialNumber", {value: Date.now()});
  if (w3.size && isValidMac(w3.value[0])) {
    result = w3.value[0];
  }
}

// 4. DeviceInfo MACAddress
if (!result) {
  let w4 = declare("InternetGatewayDevice.DeviceInfo.MACAddress", {value: Date.now()});
  if (w4.size && isValidMac(w4.value[0])) {
    result = w4.value[0];
  }
}

// 5. LANDevice LANHostConfigManagement MAC
if (!result) {
  let w5 = declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.MACAddress", {value: Date.now()});
  if (w5.size && isValidMac(w5.value[0])) {
    result = w5.value[0];
  }
}

// 6. WLAN BSSID fallback
if (!result) {
  let w6 = declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.BSSID", {value: Date.now()});
  if (w6.size && isValidMac(w6.value[0])) {
    result = w6.value[0];
  }
}

// 7. TR-181 standard Ethernet Interface MAC
if (!result) {
  let w7 = declare("Device.Ethernet.Interface.*.MACAddress", {value: Date.now()});
  for (let p of w7) {
    if (p.value && isValidMac(p.value[0])) {
      result = p.value[0];
      break;
    }
  }
}

return {writable: false, value: [result, "xsd:string"]};

// PPPoE Password
let pw = "";
if (args[1].value) {
  pw = args[1].value[0];
  declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Password", null, {value: pw});
}
else {
  let v1 = declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Password", {value: Date.now()});

  if (v1.size) {
    pw = v1.value[0];
  }
}

return {writable: true, value: [pw, "xsd:string"]};

// pppUsername

const brand = declare('DeviceID.Manufacturer', {value: 1}).value[0];
let result = '';
const now = Date.now();

if ("value" in args[1]) {
    result = args[1].value[0];
} else {
    let keys = [
        'InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Username',
        'Device.PPP.Interface.*.Username',
    ];

    result = getParameterValue(keys);
}

log('pppUsername: ' + result);
return {writable: false, value: [result, "xsd:string"]};

function getParameterValue(keys) {
    for (let key of keys) {
        let d = declare(key, {path: now, value: now});

        for (let item of d) {
            if (item.value && item.value[0]) {
                return item.value[0];
            }
        }
    }

    return '-';
}

// pppoe User (index page)
let result = '';

if ("value" in args[1]) {
    result = args[1].value[0];
}

if (result === '') {
    let keys = [
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.1.WANPPPConnection.1.Username',
        'InternetGatewayDevice.WANDevice.*.WANConnectionDevice.1.WANPPPConnection.2.Username',
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.2.WANPPPConnection.1.Username',
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.2.WANPPPConnection.2.Username',
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.3.WANPPPConnection.1.Username',
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.3.WANPPPConnection.2.Username',
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.4.WANPPPConnection.1.Username',
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.4.WANPPPConnection.2.Username',
        'InternetGatewayDevice.WANDevice.1.WANConnectionDevice.5.WANPPPConnection.1.Username',
        'InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Username',
    ];

    result = getParameterValue(keys);
}

log("pppoeIP: " + result);
return {writable: false, value: [result, "xsd:string"]};

function getParameterValue(keys) {
    for (let key of keys) {
        if (key.includes('WANPPPConnection.1.Username')) {
            let connectionTypeKey = key.replace('Username', 'ConnectionType');
